// debugging http://shadertoy.com/view/X3VyzW in 2D where I can see the problems

// I think I've got it now!  mostly.  Just needs cleanup and put the fixes back into 3D octree version.

// based on abje http://shadertoy.com/view/4sVfWw
// instead of instanced shapes at various scales,
// surf which level sampling some complex shape at, 
// based on full, empty, surface classification

// TODO mix with e.g. http://shadertoy.com/view/M3fSWs

// TODO I still intend to try to simplify the algorithm more; 
// there were several parts about it that I found confusing.

//#define coarseness 1. // TODO want to control size of biggest quadtree cell (always subdivide up to this)
// somehow when I try, it breaks everything

// in original, it seems detail -1 means don't subdivide at all, 0 means subdivide once, 1 means subdivide twice, etc.  bizarre!
// FIXME change this so it makes sense, just subtract one from each place it's used, replace detailkludge
#define detailkludge 1
// trying to get my stuff to match abje's stuff
#define detail (5-detailkludge)
// FIXME something seems to be consuming more steps than expected, as I only witness far fewer cell intersections (22?) before it gives up
// probably the algo hopping up and down between tree levels counts as a step and during some steps, no forward progress is made
#define steps 64
#define time (iTime*0.1)
#define maxdistance 5.0

#define drawgrid 1
#define centers 0
#define intersections 1
#define showtracedcells 1

#define raymarchhybrid 96 //0 //
#define tintlevels 1
#define cutawayfront 0
#define cutawayhole 0
#define cutawaysdf 0

#define pi radians(180.)

#define rot(a) mat2(cos(a), sin(a),-sin(a), cos(a))

#define sqr(a) dot(a, a)

// following iq method
float dBox(vec2 q, vec2 e)
{
    q = abs(q) - e;
    float g = max(q.x, q.y);
    return g <= 0. ? g : length(max(q, 0.));
}

float dDiamond(vec2 p, float s) // 2D conversion of iq shape - idk if it works
{
    p = abs(p);
    float m = p.x + p.y - s;
         if (2.*p.x < m) p = p.xy;
    else if (2.*p.y < m) p = p.yx;
    else return m * sqrt(1./2.);
    return length(p - vec2(0,s));
}


float shape(vec2 q)
{
    float d;
    //d = length(q) - .4; //d = length(q) - 1.5; //
    //d = abs(length(q) - .8) - .2;
    d = length(vec2(abs(q.x) - 1.0, q.y)) - .56; // torus slice
    //d = length(vec2(length(q) - 1.0, q.y)) - .66; // torus?! no
    //d = .7 * sqrt(1./2.) * (abs(q.x) + abs(q.y)) - .5; // simple octahedron
    //d = dBox(q, vec2(.75, .64)) - .16;
    //d = dDiamond(q, 1.1) - .1;
 #if cutawaysdf
    d = max(d, .45 - max(abs(q.x), abs(q.y)));   // chops a square hole thru the object sdf
 #endif
    return d;
}

// at first I enabled the inner raymarchhybrid feature to show copies of shapes within the cubes.
// now I've gone past that multilevel truchet style, and am showing some larger shape.

// 0 is empty, 1 is subdivide and 2 is full
int getvoxel(vec2 p, float size) 
{
///    p += .5 * size; // spalmer kludge - I think lro arg is already relative cell center, but without this, it looks really skewed... so I'm confused I suppose
 #if cutawayhole
    if (max(abs(p.x + .0), abs(p.y + .0)) < .15) {
        return 0; // chops a square hole thru the object in a way that exposes the octree cells
    }
 #endif
 #if cutawayfront
    if (p.y > .0) {
        return 0; // chops front half
    }
 #endif
    // subdivide according to shape function adjacency - does the cell contain the shape (probably?)
    float d = shape(p);
    // in 2D it's sqrt(2.), not sqrt(3.)!
    float lim = sqrt(2.) * .5 * size;
    if (d > lim) {
        return 0;
    } else if (d > -lim) {
        return 1;
    } else {
        return 2;
    }
}


// ray-cube intersection, on the inside of the cube
// ird = 1. / abs(rd)
vec2 voxel(vec2 ro, vec2 rd, vec2 ird, float size)
{
    size *= .5;
    return (size - sign(rd) * (ro - size)) * ird;
}

float map(vec2 w) // w = world space position
{
    return shape(w);
}

vec2 grad(vec2 p, float epsilon)
{
    vec2 e = vec2(0, epsilon);
    return vec2(
        map(p + e.yx), 
        map(p + e.xy)
        ) - map(p);
}

// for debugging
float dSeg(vec2 q, vec2 a, vec2 b)
{    
	q -= a; b -= a;
	return length(q - clamp(dot(q, b) / dot(b, b), 0., 1.) * b);
}

vec3 trace(vec2 ro, vec2 rd, vec2 q, vec2 mn)
{
    vec2 mo = ro; // save
    vec2 r = iResolution.xy;
    vec3 c; // returned
    float size = 1.;

    //size *= coarseness; // wasn't working as expected yet
    vec2 fro = floor(ro / size) * size; // current cell "origin"
    vec2 lro = ro - fro; // "fractional" offset within cell
    vec2 ird = 1.0 / max(abs(rd), 1e-4);
    vec2 mask;
    vec2 lastmask;
    bool exitoct = false;
    bool yhit = false;
    int recursions = 0;
    float dist = 0.0;
    float fdist = 0.0;
    float edge = 1.0, edge2 = 1.0;
    float e = 1e-4; // / size;
    int celltraced = 0;

    float dintersect = 9e9;
    float dcellcenter = 9e9;
    float dhitshape = 9e9;

    // quadtree traversal loop
    // each iteration either:
    // - check if need to go up a level
    // - check if need to go down a level
    // - check if hit a solid cell or what
    // - march fine detail if cell is not empty and we're at max subdivision
    // - go one step forward if cell is empty
    // - repeat if did not hit a solid cell
    int i;
    for (i = 0; i < steps; ++i)
    {
        if (dist > maxdistance) break;

        vec2 cp = lro + fro; //dist * rd + ro; // current point along ray, probably at a cell boundary
        float dp = length(q - cp);
        if (dp < dintersect) dintersect = dp;
        vec2 cc = fro + .5 * size; //(floor(cp / size) + .5) * size; //(floor(cp / size) + .5) * size; //
        float dcc = length(q - cc);
        if (dcc < dcellcenter) dcellcenter = dcc;

        // go up a level?
        if (exitoct)
        {
            vec2 newfro = floor(fro / (size * 2.0)) * (size * 2.0);

            lro += fro - newfro;
            fro = newfro;

            --recursions;
            size *= 2.0;

            exitoct = (recursions > 0) && 
              (abs(dot(mod(fro / size + 0.5, 2.0) - 1.0 + mask * sign(rd) * 0.5, mask)) < 0.1);
        }
        else
        {
            if (ivec2(floor(cc / size)) == ivec2(floor(q / size))) ++celltraced;
            // checking what type of cell it is: empty, full or subdivide
            int voxelstate = getvoxel(cc/*fro*/, size);
            //voxelstate = 0; // HACK force no subdivision so I can debug the basic cell traversal

            if (voxelstate == 1 && recursions > detail-detailkludge)
            {
                voxelstate = 2; //0;
            }

            if (voxelstate == 1 && recursions <= detail-detailkludge)
            {
                //if (recursions > detail-detailkludge) break;

                ++recursions;
                size *= 0.5;

                // find which of the 4 voxels will be entered
                vec2 mask2 = step(vec2(size), lro);
                fro += mask2 * size;
                lro -= mask2 * size;

                continue;
            }
            // move forward
            else 
            if (voxelstate == 0 || voxelstate == 2)
            {
                // raycast and find distance to nearest voxel surface in ray direction
                // don't need to use voxel() every time, but do anyway
                vec2 hit = voxel(lro, rd, ird, size);

                /*if (hit.x < min(hit.y,hit.z)) {
                    mask = vec3(1,0,0);
                } else if (hit.y < hit.z) {
                    mask = vec3(0,1,0);
                } else {
                    mask = vec3(0,0,1);
                }*/
                mask = vec2(lessThan(hit, hit.yx));
                float len = dot(hit, mask);
             #if 1
                if (voxelstate == 2) { //> 0) { //
                 #if raymarchhybrid
                    //if (length(fro - ro) > 20.0 * size) break; // detail only near camera!
                    vec2 p = 1.*lro + fro; //lro; // / size;
                    float d = 0.0;
                    e = .5 / r.y; //3e-2 * dist; // / size;
                    for (int j = 0; j < raymarchhybrid; ++j) {
                        float l = map(p);
                        if (l < e || d > len) {
                            if (l < e && d <= len) yhit = true; // hit past cell bound?
                            d = min(len, d);
                            break;
                        }
                        p += l * rd;
                        d += l;
                    }
                    if (yhit) {
                        dist += d; // * size;
                        dhitshape = length(dist * rd + ro - q);
                        break;
                    }
                 #else
                    break;
                 #endif
                }
             #endif

                // move forward in ray direction, and check if need to go up a level
                dist += len;
                fdist += len;
                vec2 msrdz = mask * sign(rd) * size;
                lro += rd * len - msrdz;
                vec2 newfro = fro + msrdz;
                exitoct = (floor(newfro / size * .5 + .25) != floor(fro / size * .5 + .25))
                       && (recursions > 0);
                fro = newfro;
                lastmask = mask;
            }
        }
     #if drawgrid
        vec2 qg = abs(lro / size - .5) * (1. - lastmask);
        edge2 = min(edge2, (.5 - max(qg.x, qg.y)) * r.y * .5 * size);
     #endif
    }
    ro += dist * rd;
    #if !raymarchhybrid
    vec2 n = -lastmask * sign(rd);
    #else
    vec2 n = normalize(grad(ro, e));
    #endif

    if (i < steps && dist < maxdistance)
    {
    	float val = fract(dot(fro, vec2(15.23, 754.345)));
        vec3 color = vec3(1);
     #if tintlevels
        if (yhit) color *= sin(vec3(0,2,4) + 2. / size) * .5 + .5;
     #endif
     //#if lighting
     //   vec3 lite = max(.5, dot(n, vec3(-1,-1,1) * .566)) * vec3(1);
     //   c = vec3(color * lite);
     //   vec3 dpl = vec3(1,-2,2) - ro;
     //   vec3 lite2 = max(.0, dot(n, normalize(dpl))) / (2.2 * sqr(dpl) + .01) * vec3(0,0.3,0);
     //   c += vec3(color * lite2);
     //#else
        c = color;
     //#endif

     //#if borders
     //   vec2 qb = abs(lro / size - .5) * (1. - lastmask);
     //   edge = clamp((.5 - max(qb.x, qb.y)) * iResolution.y * .25 * size / dist, 0., 1.);
     //   if (yhit)
     //   c += (1. - edge) * (1. - c); //c = mix(vec3(1), c, edge); // white cell borders
     //#endif

     //#if drawgrid
     //   c *= edge2;
     //#endif
   } else {
     //#if drawgrid
     //   c = vec3(edge2);
     //#endif
   }

  #if 1
    // debug the quadtree itself
    size = 1.; vec2 snapq = q;
    for (int i = 0; ; size *= .5)
    {
        vec2 cq = (floor(q / size) + .5) * size;
        snapq = cq;
        int clq = getvoxel(cq, size);
        if (clq != 1 || i++ > detail - detailkludge) break;
    }
  #endif

    int classify = getvoxel(snapq, size);
    c = vec3(0);
  #if tintlevels
    c = sin(vec3(0,2,4) - 1.1 / size) * .5 + .5;
  #endif

    float aa = .5 * r.y;

    vec3 bg = classify == 0 ? vec3(0) : classify == 1 ? vec3(0,0,1) : vec3(0,1,0);
    c = mix(c, bg, .1); // debugging
 #if drawgrid //borders || 
    vec2 qc = abs((q - snapq) * 1. / size - .0);
    float edgeq = clamp((.5 - max(qc.x, qc.y)) * size * aa, 0., 1.);
    c += (1. - edgeq) * (1. - c); //c = mix(vec3(1), c, edge); // white cell borders
 #endif
    float de = abs(shape(q)) - 2.5 / r.y;
    c = mix(c, vec3(0,0,0), clamp(.5 - de * aa, 0., 1.));
    vec2 m2 = maxdistance * rd + mo; //mn; //
    float ds = dSeg(q, mo, m2) - .5 / r.y;
    c = mix(c, vec3(1,1,0), clamp(.5 - ds * aa, 0., 1.));
 #if 0 && centers
    float dc = length(q - snapq) - 3.5 / r.y;
    c = mix(c, vec3(0,1,1), clamp(.5 - dc * aa, 0., 1.));
 #endif
 #if intersections
    c = mix(c, vec3(.1), clamp(3.5 - dintersect * aa, 0., 1.));
 #endif
 #if 1 && centers
    c = mix(c, vec3(1,1,.2), clamp(3.5 - dcellcenter * aa, 0., 1.));
 #endif
 #if showtracedcells
    c = mix(c, vec3(1), .3 - .3 * cos(7. * float(celltraced) * iTime)); // blink brighten
 #endif
 #if raymarchhybrid
    c = mix(c, vec3(0,0,1), clamp(2.5 - dhitshape * aa, 0., 1.));
 #endif

    return c;
}

void mainImage(out vec4 fragColor, vec2 fragCoord)
{
    vec4 m = iMouse;
    vec2 r = iResolution.xy,
        q = (2. * fragCoord.xy - r) / r.y;
    vec2
        mo = (2. * abs(m.zw) - r) / r.y, 
        mn = (2. * abs(m.xy) - r) / r.y,
        ro = mo,
        rd = normalize(mn - mo);
    if (m.z <= .0) { //true) { //m == vec4(0)) { //
        ro = mo = vec2(.0 + .9 * sin(5. * time), .0 + .5 * cos(time));
        rd = sin(vec2(.5 * pi, 0) + 3. * time);
        mn = ro + rd;
    }

    vec3 c = trace(ro, rd, q, mn);

    fragColor = vec4(sqrt(c), 1);
}

